// ===== Строки интерфейса =====
// Все тексты приложения живут здесь, t('key') возвращает строку (или сам ключ,
// если строки нет). Статический HTML подставляется через атрибуты data-i18n /
// data-i18n-ph / data-i18n-html. Узбекский язык убран 21.11.2026 по решению
// владельца — остался только русский.

let _lang = 'ru';
try { localStorage.removeItem('slon-lang'); } catch(e) {}

// Перевод по ключу. Плейсхолдеры {name} подставляются из vars.
function t(key, vars) {
  let s = I18N.ru[key] != null ? I18N.ru[key] : key;
  if(vars) for(const k in vars) s = s.replace(new RegExp('\\{'+k+'\\}','g'), vars[k]);
  return s;
}
// Алиас t() для файлов, где переменная `t` уже занята (напр. tasks.js: taskHTML(t) — объект задачи).
function tr(key, vars) { return t(key, vars); }

// Название дня аттестации в нужной форме. День свой у каждого филиала, поэтому
// склонять его подстановкой нельзя — храним готовые формы по ISO-номеру дня:
//   name «суббота» · when «в субботу» · every «по субботам»
//   until «субботы» (не дожидаясь …) · before «перед субботой»
function quizDayWord(form, weekday) {
  return t('quizday.' + (weekday || myQuizWeekday()) + '.' + form);
}

// Дата по-русски. opts как у toLocaleDateString:
// { weekday:'long'|'short', day:'numeric', month:'long'|'short', year:'numeric' }.
function fmtLocale(dateInput, opts) {
  opts = opts || { day:'numeric', month:'short' };
  const d = dateInput instanceof Date ? dateInput : new Date(dateInput);
  if(isNaN(d)) return String(dateInput == null ? '' : dateInput);
  return d.toLocaleDateString('ru-RU', opts);
}

// Применить перевод к статическому HTML (вызывается на старте и не требует повторного вызова
// при переключении — там перезагрузка). data-i18n → textContent, -ph → placeholder, -html → innerHTML.
function applyStaticI18n(root) {
  root = root || document;
  root.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.getAttribute('data-i18n')); });
  root.querySelectorAll('[data-i18n-ph]').forEach(el => { el.setAttribute('placeholder', t(el.getAttribute('data-i18n-ph'))); });
  root.querySelectorAll('[data-i18n-html]').forEach(el => { el.innerHTML = t(el.getAttribute('data-i18n-html')); });
  root.querySelectorAll('[data-i18n-label]').forEach(el => { el.setAttribute('label', t(el.getAttribute('data-i18n-label'))); }); // <optgroup label>
  try { document.documentElement.setAttribute('lang', _lang); } catch(e) {}
}

